<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Moje zadania'; ?>
<div class="page-head"><div><p class="eyebrow">Praca</p><h1>Moje zadania</h1></div></div>
<form class="filter-bar card" method="get" action="<?=Html::e(Url::to('/tasks'))?>"><label>Status<select name="filter"><option value="open" <?=$filter==='open'?'selected':''?>>Otwarte</option><option value="done" <?=$filter==='done'?'selected':''?>>Wykonane</option><option value="overdue" <?=$filter==='overdue'?'selected':''?>>Po terminie</option><option value="all" <?=$filter==='all'?'selected':''?>>Wszystkie</option></select></label><label>Przestrzeń<select name="space"><option value="0">Wszystkie</option><?php foreach($spaces as $s):?><option value="<?=Html::e($s['id'])?>" <?=(int)($spaceId??0)===(int)$s['id']?'selected':''?>><?=Html::e($s['name'])?></option><?php endforeach;?></select></label><button class="button">Filtruj</button></form>
<section class="card"><?php if(!$tasks):?><div class="empty-state"><h2>Brak zadań</h2><p class="muted">W tym widoku nie ma zadań spełniających wybrane kryteria.</p></div><?php endif;?><?php foreach($tasks as $task):?><div class="task-row <?=$task['status']==='done'?'completed':''?>"><div><a href="<?=Html::e(Url::to('/pages/'.$task['page_id'].'#tasks'))?>"><strong><?=Html::e($task['description'])?></strong></a><p class="muted"><?=Html::e($task['space_name'])?> · <?=Html::e($task['page_title'])?><?php if($task['due_date']):?> · termin <?=Html::e($task['due_date'])?><?php endif;?></p></div><form method="post" action="<?=Html::e(Url::to('/tasks/'.$task['id'].'/complete'))?>"><?=Csrf::field()?><input type="hidden" name="completed" value="<?=$task['status']==='done'?'0':'1'?>"><button class="button secondary"><?=$task['status']==='done'?'Otwórz ponownie':'Oznacz jako wykonane'?></button></form></div><?php endforeach;?></section>
